class CaptionGlossTests(unittest.TestCase):
 def test_pipeline_matches_plain_and_prior_complex_expectations(self):
  for i,c in enumerate(CASES):
   with self.subTest(case=i):self.assertEqual(MODULE.repair_formula_delimiters(c['source']),c['pythonExpected'])
 def test_new_step_skips_complex_and_is_idempotent(self):
  for i,c in enumerate(CASES):
   with self.subTest(case=i):
    result=MODULE.repair_caption_quoted_gloss_links(c['source'])
    if c['complexSkip']:self.assertEqual(result,c['source'])
    self.assertEqual(MODULE.repair_caption_quoted_gloss_links(result),result)
